#!/usr/bin/env node
/**
 * Install Git Hooks — 安装 Git 强制门禁
 * 
 * 职责：自动安装 pre-commit hook，确保代码必须通过工作流门禁
 * 
 * Usage:
 *   node workflow/tools/install-git-hooks.js [--force]
 */

'use strict';

const fs = require('fs');
const path = require('path');

// 预提交 hook 模板
const PRE_COMMIT_HOOK = `#!/bin/bash
# WorkFlowAgent Pre-Commit Hook — 强制工作流门禁
# Auto-generated by install-git-hooks.js
# DO NOT MODIFY MANUALLY

set -e

echo "🔒 WorkFlowAgent 门禁检查启动..."

# 运行门禁检查
node "$(git rev-parse --show-toplevel)/workflow/scripts/total-gate.js" --mode pre-commit

# 门禁通过，允许 commit
exit 0
`;

const PRE_COMMIT_HOOK_WIN = `@echo off
REM WorkFlowAgent Pre-Commit Hook — 强制工作流门禁

echo 🔒 WorkFlowAgent 门禁检查启动...

REM 获取项目根目录
for /f "tokens=*" %%a in ('git rev-parse --show-toplevel') do set PROJECT_ROOT=%%a

REM 运行门禁检查
node "%PROJECT_ROOT%\\workflow\\scripts\\total-gate.js" --mode pre-commit

REM 门禁通过，允许 commit
exit /b %errorlevel%
`;

function installHooks(projectRoot, options = {}) {
  const gitDir = path.join(projectRoot, '.git');
  const hooksDir = path.join(gitDir, 'hooks');
  
  // 检查是否是 git 仓库
  if (!fs.existsSync(gitDir)) {
    console.error('❌ 当前目录不是 Git 仓库');
    return { success: false, reason: 'Not a git repository' };
  }
  
  // 确保 hooks 目录存在
  if (!fs.existsSync(hooksDir)) {
    fs.mkdirSync(hooksDir, { recursive: true });
  }
  
  const isWindows = process.platform === 'win32';
  const hookContent = isWindows ? PRE_COMMIT_HOOK_WIN : PRE_COMMIT_HOOK;
  const hookPath = path.join(hooksDir, 'pre-commit');
  
  // 检查是否已存在 hook
  if (fs.existsSync(hookPath) && !options.force) {
    console.log('⚠️ pre-commit hook 已存在，使用 --force 覆盖');
    return { success: false, reason: 'Hook already exists' };
  }
  
  // 写入 hook
  fs.writeFileSync(hookPath, hookContent, { mode: 0o755 });
  
  console.log('✅ Git pre-commit hook 安装成功');
  console.log(`   位置: ${hookPath}`);
  console.log('   效果: 未经工作流的代码修改将被阻断提交');
  
  return { success: true, hookPath };
}

function uninstallHooks(projectRoot) {
  const hooksDir = path.join(projectRoot, '.git', 'hooks');
  const hookPath = path.join(hooksDir, 'pre-commit');
  
  if (!fs.existsSync(hookPath)) {
    console.log('ℹ️ 没有可卸载的 hook');
    return { success: true, existed: false };
  }
  
  // 检查是否是我们的 hook
  const content = fs.readFileSync(hookPath, 'utf-8');
  if (!content.includes('WorkFlowAgent')) {
    console.log('⚠️ pre-commit hook 不是 WorkFlowAgent 生成的，跳过卸载');
    return { success: false, reason: 'Not a WorkFlowAgent hook' };
  }
  
  fs.unlinkSync(hookPath);
  console.log('✅ Git pre-commit hook 已卸载');
  
  return { success: true, existed: true };
}

// CLI 入口
function main() {
  const args = process.argv.slice(2);
  const projectRoot = process.cwd();
  
  if (args.includes('--uninstall')) {
    return uninstallHooks(projectRoot);
  }
  
  const force = args.includes('--force');
  return installHooks(projectRoot, { force });
}

// 如果直接运行
if (require.main === module) {
  const result = main();
  process.exit(result.success ? 0 : 1);
}

module.exports = { installHooks, uninstallHooks };
